// TaxpayerCreate Examples: {"display_name":"Ana (personal)","person_type":"fisica","regimes":[{"options":{"deduction_mode":"blind_35"},"regime_code":"606","start_period":"2026-01"}],"rfc":"GOMA800101AB6"}
